35	export const useReactionActions = ({ memo, onComplete }: UseReactionActionsOptions) => {
36	  const currentUser = useCurrentUser();
37	  const queryClient = useQueryClient();
38	
39	  const hasReacted = (reactionType: string) => {
40	    return memo.reactions.some((r) => r.reactionType === reactionType && r.creator === currentUser?.name);
41	  };
42	
43	  const handleReactionClick = async (reactionType: string) => {
44	    if (!currentUser) return;
45	
46	    try {
47	      if (hasReacted(reactionType)) {
48	        const reactions = memo.reactions.filter(
49	          (reaction) => reaction.reactionType === reactionType && reaction.creator === currentUser.name,
50	        );
51	        await Promise.all(reactions.map((reaction) => memoServiceClient.deleteMemoReaction({ name: reaction.name })));
52	      } else {
53	        await memoServiceClient.upsertMemoReaction({
54	          name: memo.name,
55	          reaction: { contentId: memo.name, reactionType },
56	        });
57	      }
58	      // Refetch the memo to get updated reactions and invalidate cache
59	      const updatedMemo = await memoServiceClient.getMemo({ name: memo.name });
60	      queryClient.setQueryData(memoKeys.detail(memo.name), updatedMemo);
61	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
62	      // If this memo is a comment, refresh the parent's comments list so the comment's reactions update in the UI
63	      if (memo.parent) {
64	        queryClient.invalidateQueries({ queryKey: memoKeys.comments(memo.parent) });
65	      }
